const monthsBetween=(first,last)=>{validateForecastPeriods([first]);validateForecastPeriods([last]);const result=[];for(let d=new Date(first+'-01T00:00:00Z');d.toISOString().slice(0,7)<=last;d.setUTCMonth(d.getUTCMonth()+1)){result.push(d.toISOString().slice(0,7));if(result.length>24)throw Error('Choose at most 24 full months.');}return validateForecastPeriods(result);};
