 for(const period of periods){const matches=publications.filter(row=>row.communityId===communityId&&row.verified===true&&row.approved===true&&row.locked===true&&row.activePeriods?.includes(period));if(matches.length!==1||!matches[0].publicationId)return [];selected.push(matches[0].publicationId);}
